// Command api is the Ortus HTTP API with the BFF session endpoints (W0.09): chi, slog JSON, HTTP_ADDR from the
// environment. Every contract operation goes through the gateway (gate.go); the routes of the OpenAPI tags are
// generated by `make gen` (router.go, tools/gen/codegen.mjs). Configuration: deploy/compose/.env.example.
//
// Exit codes: 0 — stopped by a signal; 1 — server failure; 2 — configuration or database unreachable at start.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"

	"github.com/ortus/ortus-crm/backend/internal/control/subscriptions"
	"github.com/ortus/ortus-crm/backend/internal/control/subscriptions/subshttp"
	"github.com/ortus/ortus-crm/backend/internal/control/tenants/operators"
	"github.com/ortus/ortus-crm/backend/internal/control/tenants/platformhttp"
	"github.com/ortus/ortus-crm/backend/internal/modules/access/invitations"
	"github.com/ortus/ortus-crm/backend/internal/modules/modulesreg"
	"github.com/ortus/ortus-crm/backend/internal/platform/authz"
	"github.com/ortus/ortus-crm/backend/internal/platform/idem"
	"github.com/ortus/ortus-crm/backend/internal/platform/notify/inbox"
	"github.com/ortus/ortus-crm/backend/internal/platform/notify/mail"
	"github.com/ortus/ortus-crm/backend/internal/platform/session"
	"github.com/ortus/ortus-crm/backend/internal/platform/session/oidc"
	"github.com/ortus/ortus-crm/backend/internal/platform/session/oidc/authhttp"
	"github.com/ortus/ortus-crm/backend/internal/platform/tenantctx"
	"github.com/ortus/ortus-crm/backend/internal/platform/tenantctx/mehttp"
)

const (
	exitOK     = 0
	exitFailed = 1
	exitConfig = 2
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	code := run(ctx, os.Getenv, os.Stdout, os.Stderr)
	stop()
	os.Exit(code)
}

func run(ctx context.Context, getenv func(string) string, stdout, stderr io.Writer) int {
	cfg, err := loadConfig(getenv)
	if err != nil {
		fmt.Fprintf(stderr, "api: configuration: %v\n", err)
		return exitConfig
	}
	log := slog.New(slog.NewJSONHandler(stdout, &slog.HandlerOptions{Level: cfg.LogLevel}))
	d, closeDeps, err := build(ctx, cfg, log, getenv)
	if err != nil {
		fmt.Fprintf(stderr, "api: %v\n", err)
		return exitConfig
	}
	srv := &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           newHandler(d),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       2 * time.Minute,
		ErrorLog:          slog.NewLogLogger(log.Handler(), slog.LevelWarn),
	}
	log.InfoContext(ctx, "api: listening", slog.String("addr", cfg.HTTPAddr), slog.String("app_env", cfg.AppEnv),
		slog.String("auth_provider", cfg.AuthProvider))
	return runServer(ctx, d, srv, closeDeps)
}

// runServer runs the background jobs of d next to serve and, on both paths, cancels them and waits for them before
// closeDeps: the LISTEN of the realtime channel holds a connection of the control pool, and pgxpool.Pool.Close blocks
// until every connection is returned — on a server failure the signal context is still live (W1.42).
func runServer(ctx context.Context, d deps, srv *http.Server, closeDeps func()) int {
	defer closeDeps()
	bg, cancel := context.WithCancel(ctx)
	var jobs sync.WaitGroup
	defer jobs.Wait()
	defer cancel()
	if d.background != nil {
		jobs.Go(func() { d.background(bg) })
	}
	return serve(ctx, srv, d.stopping, d.log)
}

// shutdownTimeout is the budget of the stop: the realtime sockets and the HTTP requests in flight.
const shutdownTimeout = 10 * time.Second

// serve runs srv until ctx ends (exitOK) or the server fails (exitFailed). stopping, if set, runs on both paths within
// the shutdown budget and before the server stops: the realtime sockets close with 1001 and are waited for
// (ADR-0015) — http.Server does not track the hijacked connections, and the process exits right after run. srv.Shutdown
// also runs on both paths: the HTTP handlers in flight end before closeDeps closes the pools (W1.42, 16.10 №2).
//
// On the signal path the listener still accepts while stopping runs: an upgrade that arrives after hub.Close is
// refused by the hub (ErrHubClosed), and one that sockets.wait has not counted yet ends with the process — harmless,
// the client reconnects to another replica.
func serve(ctx context.Context, srv *http.Server, stopping func(context.Context), log *slog.Logger) int {
	errc := make(chan error, 1)
	go func() { errc <- srv.ListenAndServe() }()
	failed := false
	select {
	case err := <-errc:
		log.ErrorContext(ctx, "api: server failed", slog.String("error", err.Error()))
		failed = true
	case <-ctx.Done():
	}
	shutdown, cancel := context.WithTimeout(context.WithoutCancel(ctx), shutdownTimeout)
	defer cancel()
	if stopping != nil {
		stopping(shutdown)
	}
	if err := srv.Shutdown(shutdown); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.ErrorContext(ctx, "api: shutdown", slog.String("error", err.Error()))
		failed = true
	}
	if failed {
		return exitFailed
	}
	return exitOK
}

// tenantStore joins what GET /me/context reads from tenant DBs: the profile (TenantData) and the capabilities
// (the evaluator of W1.04 over the same grants).
type tenantStore struct {
	tenantctx.TenantData
	*authz.Evaluator
}

// newEvaluator is the permission evaluator of W1.04 over source (the permission cache of the realtime channel, W1.42)
// and the unit tree of the tenant pools, with the clock of the application (APP_FIXED_NOW outside prod).
func newEvaluator(pools *tenantctx.Pools, source authz.Source, cfg config) *authz.Evaluator {
	return authz.New(source, authz.PGSource{Pools: pools}, cfg.clock())
}

// build connects the control DB (role ortus_api) and wires the platform: directory, tenant pools (secret_ref +
// sentinel), the permission evaluator, durable BFF sessions in the control DB (W1.03), the idempotency guard, the
// strict servers of the tags Context (with selectTenant) and Auth (OIDC sign-in, logout, invitations), Platform.
func build(ctx context.Context, cfg config, log *slog.Logger, getenv func(string) string) (deps, func(), error) {
	// W1.41: the SMTP of the invitation letters (SMTP_HOST, SMTP_PORT, MAIL_FROM, PUBLIC_ORIGIN); without SMTP_HOST
	// outside prod the letters are off.
	mailCfg, err := mail.FromEnv(getenv, cfg.AppEnv)
	if err != nil {
		return deps{}, nil, fmt.Errorf("mail: %w", err)
	}
	log.InfoContext(ctx, "api: mail", slog.Bool("enabled", mailCfg.Enabled()), slog.String("smtp_host", mailCfg.Host),
		slog.Int("smtp_port", mailCfg.Port), slog.String("public_origin", mailCfg.Origin))
	pcfg, err := pgxpool.ParseConfig(cfg.ControlDBURL)
	if err != nil {
		return deps{}, nil, errors.New("CONTROL_DB_URL is not a valid PostgreSQL DSN") // the parse error quotes the DSN
	}
	control, err := pgxpool.NewWithConfig(ctx, pcfg)
	if err != nil {
		return deps{}, nil, fmt.Errorf("control DB: %w", err)
	}
	if err := control.Ping(ctx); err != nil {
		control.Close()
		return deps{}, nil, fmt.Errorf("control DB %s/%s unreachable: %w", pcfg.ConnConfig.Host, pcfg.ConnConfig.Database, err)
	}
	dir := tenantctx.NewPGDirectory(control)
	pools := tenantctx.NewPools(dir, getenv, cfg.TenantDBHost)
	// S1-02 (W1.02): the control DB is never a tenant DB, whatever its name.
	pools.Reserved = []string{pcfg.ConnConfig.Database}
	controlSQL := stdlib.OpenDBFromPool(control)
	data := tenantctx.TenantData{Pools: pools}
	sessions := oidc.NewPGSessionStore(control) // Q-W0.09-8: sessions survive the process and serve every replica
	// W1.42 (ADR-0015): the permission cache, the gateway and the tickets of the realtime channel; the gateway checks
	// the session of a ticket in the store of session.Manager.
	ch := newChannel(pools, control, sessions, cfg, log)
	ev := newEvaluator(pools, ch.cache, cfg)
	manager := &session.Manager{
		CookieName: cfg.SessionCookie, CSRFCookieName: csrfCookie, TTL: cfg.SessionTTL,
		AllowedOrigins: cfg.AllowedOrigins, Secure: cfg.CookieSecure, Store: sessions,
	}
	auth := &authhttp.Server{
		Sessions: manager, Logins: oidc.NewPGLoginStore(control), Providers: providers(cfg),
		Accounts: oidc.NewPGAccounts(control), Revoker: sessions,
		Invitations: &invitations.Service{Control: control, Tenants: pools}, Realtime: ch.tickets, Log: log,
	}
	every, err := sweepInterval(getenv, cfg.AppEnv)
	if err != nil {
		_ = controlSQL.Close()
		control.Close()
		return deps{}, nil, err
	}
	filesSrv, billingSrv, err := filesServers(pools, ev, getenv, log) // W1.09
	if err != nil {
		pools.Close()
		_ = controlSQL.Close()
		control.Close()
		return deps{}, nil, err
	}
	// W1.08: the module registry, the subscription of the control DB and their parts of /me/context.
	modules, subs := newModules(pools, cfg), subscriptions.Store{DB: controlSQL, Now: cfg.clock()}
	// W1.05; W1.03 and W1.06 embed theirs (access.go); W1.41: inviteMember sends the letter with the link.
	access := newAccessServer(pools, ev, control, cfg.clock())
	access.assignmentsHandler = access.WithInvitationMail( // assignments.Handler (embedded)
		mail.Invitations{Sender: mail.New(mailCfg, log), Origin: mailCfg.Origin})
	d := deps{
		cfg:      cfg,
		log:      log,
		dir:      dir,
		sessions: manager,
		authz:    authz.Gateway{E: ev},
		servers: Servers{
			Context: &mehttp.Server{
				Dir: dir, TenantDB: tenantStore{TenantData: data, Evaluator: ev},
				LastTenants: mehttp.NewPGLastTenants(control), Log: log,
				Inbox:  &inbox.Inbox{Pools: pools, Audience: inbox.AuthzAudience{E: ev}}, // W1.10: /me/notifications
				Extras: meExtras{subs: subs, modules: modules, pools: pools},             // W1.08: modules, tenantState
			},
			Auth: auth,
			Platform: subshttp.PlatformServer{ // W1.08: subscriptions over the operator commands (W1.48) and the registry (W1.02)
				StrictServerInterface: &operators.Server{
					Server: &platformhttp.Server{Store: platformhttp.SQLStore{Control: controlSQL}},
					// Q-W1.48-12 (W1.42): the members of a suspended, resumed, extended or renamed tenant get context.changed.
					Commands: hintingCommands{
						Commands: &operators.Service{Control: controlSQL, Now: cfg.clock()}, hint: ch.tenantChanged, log: log,
					},
				},
				Subs: subs,
			},
			Files:   filesSrv,                                    // W1.09
			Billing: subshttp.NewBillingServer(billingSrv, subs), // W1.09: storage; W1.08: subscription over it
			Modules: &modulesreg.Server{S: modules},              // W1.08
			Access:  access,                                      // W1.05, W1.06, W1.41 (above)
		},
		replays: map[string]replayFunc{"logout": auth.ReplayLogout},
		ready:   control.Ping,
		// S1-25: tenant keys in core.idempotency_keys of the tenant DB; identity and platform operations in
		// idempotency_keys of the control DB (control 0005, W1.48: tenant + actor + operation).
		idem: &idem.Guard{Stores: idem.TenantStores{Pools: pools, Platform: operators.Keys{DB: controlSQL}}, Log: log},
		// W1.08: the module gate (AC-12) and the subscription lifecycle (AC-11, SUBSCRIPTION_SWEEP_INTERVAL); W1.42: the
		// LISTEN of the realtime hints next to it.
		modules:    modulesreg.Gate{S: modules},
		background: together(lifecycle(subs, every, log), ch.listen),
		newcomers:  auth.Accounts, // W1.50: a first dev login creates the account as the first OIDC sign-in
		realtime:   ch.handler(),  // W1.42: GET /api/v1/realtime
		stopping:   ch.stop,       // W1.42: http.Server does not track the hijacked sockets
	}
	return d, func() {
		pools.Close()
		_ = controlSQL.Close()
		control.Close()
	}, nil
}

// providers are the OIDC clients of the configuration: the realm of clients and, if set, of operators.
func providers(cfg config) authhttp.Providers {
	var out authhttp.Providers
	for key, p := range map[string]*providerConfig{authhttp.ProviderUsers: cfg.Users, authhttp.ProviderOperators: cfg.Operators} {
		if p != nil {
			out = append(out, oidc.NewProvider(oidc.Config{
				Key: key, Issuer: p.Issuer, ClientID: p.ClientID, ClientSecret: p.ClientSecret,
				RedirectURL: p.RedirectURL, PostLogoutRedirectURL: p.PostLogoutRedirectURL,
			}))
		}
	}
	return out
}
